def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)
    ex = enemy.x
    ey = enemy.y
    h = radians(enemy.heading)
    fx = cos(h)
    fy = sin(h)
    dx = me.x - ex
    dy = me.y - ey
    dist = hypot(dx, dy)
    a = dx * fx + dy * fy
    b = dx * (-fy) + dy * fx
    if abs(b) < 0.1:
        sb = 1.0
    else:
        sb = 1.0 if b > 0 else -1.0
    al = enemy.armor.get("left", 0.0)
    ar = enemy.armor.get("right", 0.0)
    if al + 0.15 < ar:
        sb = 1.0
    elif ar + 0.15 < al:
        sb = -1.0
    if a > 0.25:
        ta = 0.0
        tb = sb * 0.45
    elif a > -0.25:
        ta = -0.15
        tb = sb * 0.35
    else:
        ta = -0.35
        tb = sb * 0.25
    tx = ex + fx * ta - fy * tb
    ty = ey + fy * ta + fx * tb
    rr = hypot(tx, ty)
    if rr > 5.4:
        k = 5.4 / rr
        tx = tx * k
        ty = ty * k
    br = bearing_to(tx, ty)
    if dist < 0.55:
        sp = 0.65
    elif dist < 1.2:
        sp = 0.9
    else:
        sp = 1.0
    if abs(br) < 10:
        return (sp, sp)
    if br > 0:
        return (0.2 * sp, sp)
    return (sp, 0.2 * sp)

